package ai.learnharness.android;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class ResearchAgentDeviceTest {
 private final android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();
 @Test public void isolatedResearchUsesOriginalPromptAndReadablePageTools()throws Exception{
  int[] calls={0};ResearchAgent.Web web=new ResearchAgent.Web(){public JSONArray search(String q,int n)throws Exception{assertEquals("pair evidence",q);return new JSONArray().put(new JSONObject().put("url","https://example.org/pair"));}public ResearchWeb.Page fetch(String url){return new ResearchWeb.Page(url,200,"text/html","<html><head><title>Pairs</title></head><body><article><h1>Pairs</h1><p>"+"A pair contains two objects. SOURCERESEARCHONLY ".repeat(50)+"</p></article><script>throw new Error('must not run')</script></body></html>");}};
  LessonAgent.Model model=new LessonAgent.Model(){public ProviderClient.Reply complete(String p,JSONArray h,JSONArray t){throw new AssertionError("Missing researcher role");}public ProviderClient.Reply completeRole(String role,String p,JSONArray h,JSONArray t)throws Exception{assertEquals("researcher",role);assertTrue("Original prompt: "+p,p.toLowerCase(java.util.Locale.ROOT).contains("research"));int step=calls[0]++;if(step==0){assertEquals(1,h.length());assertTrue(h.toString().contains("Research question: Pairs?"));return tool("web_search",new JSONObject().put("query","pair evidence"));}if(step==1)return tool("web_fetch",new JSONObject().put("url","https://example.org/pair"));assertTrue("Page tool output: "+h,h.toString().contains("SOURCERESEARCHONLY"));assertFalse(h.toString().contains("must not run"));return new ProviderClient.Reply("Pairs have two objects. [Evidence](https://example.org/pair)",3,2);}};
  try(OriginalCore foreground=new OriginalCore(context)){JSONObject result=new ResearchAgent(context).run(new JSONObject().put("question","Pairs?"),model,web,null);assertEquals(3,calls[0]);assertEquals(9,result.getLong("inputTokens"));assertEquals(1,result.getJSONArray("sources").length());assertEquals("https://example.org/pair",result.getJSONArray("sources").getJSONObject(0).getString("url"));assertTrue(foreground.call(new JSONObject().put("operation","researchSetup")).getBoolean("ok"));}
 }
 private ProviderClient.Reply tool(String name,JSONObject args)throws Exception{return new ProviderClient.Reply("",3,2,new JSONArray().put(ToolProtocol.call("call_"+name,name,args.toString())),null);}
 @Test public void durableJobsActivateOnlyAfterParentCommitAndRetryHasFreshIdentity()throws Exception{
  String filename="jobs-test-"+java.util.UUID.randomUUID()+".json";JobStore store=new JobStore(context,filename);
  try{JSONObject route=new JSONObject().put("billing","api").put("provider","OpenAI").put("endpoint","https://api.openai.com/v1").put("model","test").put("thinking","default");JSONObject job=store.create("session","call","research",new JSONObject().put("question","Pairs?"),route);assertEquals(job.getString("id"),store.create("session","call","research",new JSONObject(),route).getString("id"));assertFalse(store.activate(new JSONArray()));assertEquals("staged",store.get(job.getString("id")).getString("status"));JSONArray sessions=new JSONArray().put(new JSONObject().put("id","session").put("agentHistory",new JSONArray().put(new JSONObject().put("role","tool").put("tool_call_id","call"))));assertTrue(store.activate(sessions));store.update(job.getString("id"),new JSONObject().put("status","running"));store.interrupted();assertEquals("interrupted",store.get(job.getString("id")).getString("status"));JSONObject retry=store.retry(job.getString("id"));assertNotEquals(job.getString("id"),retry.getString("id"));assertEquals("queued",retry.getString("status"));assertEquals(2,new JobStore(context,filename).list().length());try{store.remove(retry.getString("id"));fail();}catch(java.io.IOException expected){} }finally{context.deleteFile(filename);context.deleteFile(filename+".bak");}
 }
 @Test public void publicWebAddressChecksRejectLocalNetworks()throws Exception{for(String ip:new String[]{"127.0.0.1","10.1.2.3","192.168.1.1","169.254.1.2","100.64.1.2","::1","fc00::1"})assertFalse(ip,ResearchWeb.publicAddress(java.net.InetAddress.getByName(ip)));assertTrue(ResearchWeb.publicAddress(java.net.InetAddress.getByName("8.8.8.8")));for(String url:new String[]{"file:///etc/passwd","http://localhost/a","https://user:pass@example.org/a"})try{ResearchWeb.publicUrl(url);fail(url);}catch(java.io.IOException expected){} }
 @Test public void planSearchDefaultsRespectDisableAndRejectApiRoleWithoutFallback()throws Exception{
  String name="search-settings-qa-"+java.util.UUID.randomUUID();android.content.SharedPreferences prefs=context.getSharedPreferences(name,0);android.content.Context scoped=new android.content.ContextWrapper(context){@Override public android.content.SharedPreferences getSharedPreferences(String ignored,int mode){return prefs;}};
  try{assertEquals("",SearchSettings.engine(prefs));prefs.edit().putBoolean("useChatGpt",true).commit();assertEquals("chatgpt",SearchSettings.engine(prefs));prefs.edit().putString("searchEngine","").commit();assertEquals("",SearchSettings.engine(prefs));JSONObject route=new JSONObject("{billing:'api',provider:'OpenAI compatible',endpoint:'https://api.openai.com/v1',model:'test',thinking:'default'}");prefs.edit().putString("searchEngine","chatgpt").putString("roleConnections",new JSONObject().put("researcher",route).toString()).commit();assertFalse(SearchSettings.available(scoped));try{new NativeModels(scoped,route,true);fail("Plan search must never use API billing");}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("No API fallback"));}}finally{context.deleteSharedPreferences(name);}
 }
}
